            "nordr" => true,
            "protocol" => "tcp",
            'destination' => array('network' => "{$lockoutif}ip", 'port' => $port),
            "descr" => "Anti lockout, prevent redirects for protected ports to this interface ip"
        );
        $fw->registerForwardRule(300, $rule);
    }
}

